(* [comment removed for export] *)
Lemma aglobals_facts :
  Forall (fun g : Z * Z * Z => let '(beg, sz, szrz) := g in
     AIMG_LO <= beg /\ beg + szrz <= AIMG_TOP /\ 0 <= sz /\ 8 * nsh sz <= szrz /\ szrz mod 8 = 0 /\ beg mod 8 = 0) aglobals.
Proof.
  (* rc.2's string globals have their own sizes (the __asan_global table); checked entry by entry by computation *)
  assert (Hb : forallb (fun g : Z * Z * Z => let '(beg, sz, szrz) := g in
      (AIMG_LO <=? beg) && (beg + szrz <=? AIMG_TOP) && (0 <=? sz) && (8 * nsh sz <=? szrz)
      && (szrz mod 8 =? 0) && (beg mod 8 =? 0)) aglobals = true) by (vm_compute; reflexivity).
  apply Forall_forall. intros [[beg sz] szrz] Hin.
  pose proof (proj1 (forallb_forall _ _) Hb _ Hin) as H. cbv beta iota zeta in H |- *.
  rewrite !andb_true_iff, !Z.leb_le, !Z.eqb_eq in H. tauto.
Qed.

