Lemma ACONST_read_stage : ltac2:(zQ "40!ot5!pjb!pic!mr6>1m$3>0@1$0^1@3$2^2$1+hggg0").
Proof.
  (* the entry is found by computation: rc.2 changed the sizes of other entries of aglobals *)
  intros m HA.
  assert (H : existsb (fun g : Z * Z * Z => let '(a, b, c) := g in (a =? AREAD_STAGE) && (b =? 65536) && (c =? 65536))
      aglobals = true) by (vm_compute; reflexivity).
  apply existsb_exists in H as [[[a b] c] [Hin Hx]].
  rewrite !andb_true_iff, !Z.eqb_eq in Hx. destruct Hx as [[-> ->] ->].
  apply (ACONST_global_addressable m AREAD_STAGE 65536 65536 HA Hin). lia.
Qed.

